/**
 * lib/chat/stickers.ts — Ledger Chat's own sticker packs.
 *
 * Two kinds of pack. The earlier packs are drawn for the app as SVG (public/stickers/<pack>/<id>.svg,
 * generated by scripts/stickers/build.ts). The packs offered since 24 November 2026 (Hoops, Hammy,
 * Noel) are raster illustrations supplied by the operator (public/stickers/<pack>/<id>.webp, lossless, metadata
 * stripped; Hammy and Noel resampled to 512 px from 256 and 128 px sources); their licence and attribution are recorded in public/stickers/CREDITS.md. A sticker
 * travels as the message text `__STICKER__img:<pack>/<id>`; the receiver renders the picture from
 * this site only, so a message can never make the client load an arbitrary URL.
 *
 * `scene` is the full-chat moment a sticker plays when it arrives or is tapped
 * (lib/chat/sticker-scenes.ts, about 4.5 s), like the screen effects of iMessage. `tint` colours the
 * scene's paint (splats, glow) when it should match the sticker.
 */

export type StickerScene =
  | 'hearts' | 'kiss' | 'hug' | 'sunrise' | 'night' | 'rain' | 'shake' | 'confetti' | 'fireworks'
  | 'sparkle' | 'splat' | 'melt' | 'boom' | 'money' | 'fire' | 'dash' | 'cool' | 'bubbles' | 'jelly' | 'snow';

export const STICKER_SCENES: readonly StickerScene[] = [
  'hearts', 'kiss', 'hug', 'sunrise', 'night', 'rain', 'shake', 'confetti', 'fireworks',
  'sparkle', 'splat', 'melt', 'boom', 'money', 'fire', 'dash', 'cool', 'bubbles', 'jelly', 'snow',
];

export interface Sticker {
  id: string;
  label: string;
  scene?: StickerScene;
  /** Paint colour for the scene (#rrggbb). */
  tint?: string;
}

export interface StickerPack {
  id: string;
  name: string;
  description: string;
  /** The sticker shown on the pack's tab. */
  cover: string;
  accent: string;
  stickers: Sticker[];
  /** Image format of the pack's files (default svg). */
  format?: 'svg' | 'webp';
  /** Width of a raster sticker in pixels: the moment never draws it larger than it can stay sharp. */
  px?: number;
  /**
   * Length of the moment in ms. The offered packs use the short, frame-breaking moment (about 2.6 s:
   * the sticker leaves its bubble, takes the whole screen without blocking a tap, and settles back);
   * the earlier packs keep the long one.
   */
  sceneMs?: number;
}

