/**
 * The packs offered in the picker (24 November 2026): Hoops, Hammy and Noel, 40 stickers. Spike, the
 * cactus, and the drawn packs are no longer offered; they stay in ALL_STICKER_PACKS so stickers
 * already sent still show.
 */
export const OFFERED_STICKER_PACK_IDS = ['hoops', 'hammy', 'noel'] as const;
export const STICKER_PACKS: readonly StickerPack[] = ALL_STICKER_PACKS.filter(p => (OFFERED_STICKER_PACK_IDS as readonly string[]).includes(p.id));

const PACKS: Record<string, StickerPack> = Object.fromEntries(ALL_STICKER_PACKS.map(p => [p.id, p]));

export const stickerMessage = (pack: string, id: string) => `__STICKER__img:${pack}/${id}`;

const RE = /^__STICKER__img:([a-z0-9-]{1,32})\/([a-z0-9-]{1,32})$/;

export interface StickerRef {
  pack: StickerPack;
  sticker: Sticker;
  src: string;
}

/** The sticker a message names, if it is one of ours. */
export function stickerRef(content: string): StickerRef | null {
  const m = RE.exec(content.trim());
  if (!m) return null;
  const pack = PACKS[m[1]];
  const sticker = pack?.stickers.find(s => s.id === m[2]);
  return pack && sticker ? { pack, sticker, src: stickerFile(pack.id, sticker.id) } : null;
}

export const stickerFile = (pack: string, id: string) => `/stickers/${pack}/${id}.${PACKS[pack]?.format ?? 'svg'}`;

/** The image path for a sticker message, or null when it is not one of ours. */
export function stickerSrc(content: string): string | null {
  return stickerRef(content)?.src ?? null;
}

export function stickerLabel(content: string): string | null {
  return stickerRef(content)?.sticker.label ?? null;
}
